INSERT IGNORE INTO `taluks` (`district_id`, `name`, `code`, `status`)
SELECT d.id, t.name, t.code, 'active'
FROM `_tmp_taluks` t
JOIN `districts` d ON d.code = t.district_code;

DROP TEMPORARY TABLE IF EXISTS `_tmp_taluks`;

